use std::process::ExitCode;

use bytemuck::{Pod, Zeroable};
use wgpu::util::DeviceExt;

const WORKGROUP_SIZE: u32 = 64;

const SHADER: &str = r#"
struct Params {
    count: u32,
    dt: f32,
}

@group(0) @binding(0) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(1) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(2) var<uniform> params: Params;

// Velocity update: reads positions only, so every acceleration of the step
// is computed from the positions the step started with.
@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let pi = pos[i];
    var acc = vec2<f32>(0.0, 0.0);
    for (var j: u32 = 0u; j < params.count; j = j + 1u) {
        if (j == i) {
            continue;
        }
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        let inv = 1.0 / (r2 * sqrt(r2));
        acc = acc + d * inv;
    }
    vel[i] = vel[i] + acc * params.dt;
}

// Position update: runs in a separate dispatch after every velocity has been
// updated, so it sees the new velocities and no position is read after it moved.
@compute @workgroup_size(64)
fn advance(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    pos[i] = pos[i] + vel[i] * params.dt;
}
"#;

#[repr(C)]
#[derive(Clone, Copy, Pod, Zeroable)]
struct Params {
    count: u32,
    dt: f32,
}

struct Input {
    count: usize,
    steps: u32,
    dt: f32,
    pos: Vec<[f32; 2]>,
    vel: Vec<[f32; 2]>,
}

fn parse_input(text: &str) -> Result<Input, String> {
    let mut tokens = text.split_whitespace();
    let mut next = |name: &str| tokens.next().ok_or_else(|| format!("missing {name}"));

    let count: usize = next("count")?
        .parse()
        .map_err(|e| format!("bad count: {e}"))?;
    let steps: u32 = next("steps")?
        .parse()
        .map_err(|e| format!("bad steps: {e}"))?;
    let dt: f32 = next("dt")?.parse().map_err(|e| format!("bad dt: {e}"))?;

    let mut pos = Vec::with_capacity(count);
    let mut vel = Vec::with_capacity(count);
    for n in 0..count {
        let mut field = |name: &str| -> Result<f32, String> {
            let tok = next(&format!("{name} of particle {n}"))?;
            tok.parse()
                .map_err(|e| format!("bad {name} of particle {n}: {e}"))
        };
        let x = field("x")?;
        let y = field("y")?;
        let vx = field("vx")?;
        let vy = field("vy")?;
        pos.push([x, y]);
        vel.push([vx, vy]);
    }

    Ok(Input {
        count,
        steps,
        dt,
        pos,
        vel,
    })
}

async fn run_steps(input: &Input) -> Result<(Vec<[f32; 2]>, Vec<[f32; 2]>), String> {
    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            ..Default::default()
        })
        .await
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("cannot create device: {e}"))?;

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("particles"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });

    let storage = wgpu::BufferUsages::STORAGE
        | wgpu::BufferUsages::COPY_DST
        | wgpu::BufferUsages::COPY_SRC;
    let pos_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("pos"),
        contents: bytemuck::cast_slice(&input.pos),
        usage: storage,
    });
    let vel_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("vel"),
        contents: bytemuck::cast_slice(&input.vel),
        usage: storage,
    });
    let params = Params {
        count: input.count as u32,
        dt: input.dt,
    };
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::bytes_of(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });

    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("layout"),
        entries: &[
            storage_entry(0, true),
            storage_entry(1, true),
            wgpu::BindGroupLayoutEntry {
                binding: 2,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
        ],
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("bind group"),
        layout: &layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: pos_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: vel_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: params_buf.as_entire_binding(),
            },
        ],
    });

    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("pipeline layout"),
        bind_group_layouts: &[Some(&layout)],
        immediate_size: 0,
    });
    let make_pipeline = |entry: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry),
            layout: Some(&pipeline_layout),
            module: &shader,
            entry_point: Some(entry),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let accelerate = make_pipeline("accelerate");
    let advance = make_pipeline("advance");

    let groups = (input.count as u32).div_ceil(WORKGROUP_SIZE);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("steps"),
    });
    for _ in 0..input.steps {
        for pipeline in [&accelerate, &advance] {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: None,
                timestamp_writes: None,
            });
            pass.set_pipeline(pipeline);
            pass.set_bind_group(0, &bind_group, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
    }

    let size = (input.count * std::mem::size_of::<[f32; 2]>()) as u64;
    let read_pos = readback_buffer(&device, size, "read pos");
    let read_vel = readback_buffer(&device, size, "read vel");
    encoder.copy_buffer_to_buffer(&pos_buf, 0, &read_pos, 0, size);
    encoder.copy_buffer_to_buffer(&vel_buf, 0, &read_vel, 0, size);
    queue.submit(Some(encoder.finish()));

    let pos = read_back(&device, &read_pos)?;
    let vel = read_back(&device, &read_vel)?;
    Ok((pos, vel))
}

fn storage_entry(binding: u32, read_write: bool) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Storage {
                read_only: !read_write,
            },
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    }
}

fn readback_buffer(device: &wgpu::Device, size: u64, label: &str) -> wgpu::Buffer {
    device.create_buffer(&wgpu::BufferDescriptor {
        label: Some(label),
        size: size.max(4),
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    })
}

fn read_back(device: &wgpu::Device, buf: &wgpu::Buffer) -> Result<Vec<[f32; 2]>, String> {
    let slice = buf.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |res| {
        let _ = tx.send(res);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("map callback lost: {e}"))?
        .map_err(|e| format!("map failed: {e}"))?;
    let data = slice.get_mapped_range();
    let out: Vec<[f32; 2]> = bytemuck::cast_slice(&data).to_vec();
    drop(data);
    buf.unmap();
    Ok(out)
}

fn summarize(pos: &[[f32; 2]], vel: &[[f32; 2]]) -> [String; 4] {
    let n = pos.len() as f64;
    let (mut cx, mut cy) = (0.0f64, 0.0f64);
    let (mut mx, mut my) = (0.0f64, 0.0f64);
    let mut kinetic = 0.0f64;
    for (p, v) in pos.iter().zip(vel) {
        cx += p[0] as f64;
        cy += p[1] as f64;
        mx += v[0] as f64;
        my += v[1] as f64;
        kinetic += (v[0] as f64 * v[0] as f64 + v[1] as f64 * v[1] as f64) / 2.0;
    }
    cx /= n;
    cy /= n;

    let mut sq = 0.0f64;
    for p in pos {
        let dx = p[0] as f64 - cx;
        let dy = p[1] as f64 - cy;
        sq += dx * dx + dy * dy;
    }
    let spread = (sq / n).sqrt();

    [
        format!("CENTER {cx:.6} {cy:.6}"),
        format!("MOMENTUM {mx:.6} {my:.6}"),
        format!("KINETIC {kinetic:.6}"),
        format!("SPREAD {spread:.6}"),
    ]
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: particles <input-file>");
        return ExitCode::FAILURE;
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            return ExitCode::FAILURE;
        }
    };
    let input = match parse_input(&text) {
        Ok(i) => i,
        Err(e) => {
            eprintln!("bad input {path}: {e}");
            return ExitCode::FAILURE;
        }
    };

    let (pos, vel) = match pollster::block_on(run_steps(&input)) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("{e}");
            return ExitCode::FAILURE;
        }
    };

    for line in summarize(&pos, &vel) {
        println!("{line}");
    }
    ExitCode::SUCCESS
}

